const nombre = prompt("Nombre");
const texto = prompt("Minutos");
const minutos = Number(texto);
console.log("Hola", nombre);
console.log("Con cinco más:", minutos + 5);

const nombre = prompt("Nombre");
const minutos = Number(prompt("Minutos"));
const dias = 5;
console.log("Nombre:", nombre);
console.log("Minutos diarios:", minutos);
console.log("Días:", dias);
console.log("Total:", minutos * dias);
